import {escape,format,resultMarkup} from './render.mjs';
import {enrichResult} from './visuals.mjs';
import {fieldPresentation} from './controls.mjs';
const $=(q,parent=document)=>parent.querySelector(q), $$=(q,parent=document)=>[...parent.querySelectorAll(q)];
const savedKey='culators.favourites.v1';
function getSaved(){try{const a=JSON.parse(localStorage.getItem(savedKey)||'[]');return Array.isArray(a)?a.filter(x=>typeof x==='string'):[];}catch{return [];}}
function setSaved(a){try{localStorage.setItem(savedKey,JSON.stringify(a));return true;}catch{return false;}}
let catalogue;
async function searchData(){if(!catalogue)catalogue=await fetch('/assets/search.json').then(r=>{if(!r.ok)throw Error('Unable to load the search index.');return r.json();});return catalogue;}
const dialog=$('#search-dialog');
async function showSearch(){dialog.showModal();const input=$('#dialog-query');input.focus();try{await searchData();showDialogResults();}catch{$('#dialog-results').textContent='Search is unavailable. Browse the categories in the menu.';}}
function showDialogResults(){const query=$('#dialog-query').value.trim().toLowerCase();const items=(catalogue||[]).filter(t=>(t.title+' '+t.description).toLowerCase().includes(query)).slice(0,15);$('#dialog-results').innerHTML=items.length?items.map(t=>`<a href="/en/${escape(t.slug)}/"><span>${escape(t.title)}</span></a>`).join(''):'<p>No matching tools. Try another word.</p>';}
$$('[data-open-search]').forEach(b=>b.addEventListener('click',showSearch));
$('[data-close-search]')?.addEventListener('click',()=>dialog.close());
dialog?.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
$('#dialog-query')?.addEventListener('input',showDialogResults);
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();showSearch();}if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();if($('#calculator-search'))$('#calculator-search').focus();else showSearch();}});
const demo=$('#demo-slider');demo?.addEventListener('input',()=>{$('#demo-value').textContent=String(Number(demo.value)*2);$('#demo-percent').textContent=demo.value;$('.demo-fill').style.transform=`scaleX(${Number(demo.value)/100})`;});
const library=$('[data-library]');
if(library){let filter='all';const input=$('#calculator-search'),items=$$('.tool-link',library),groups=$$('.directory-group',library);function update(){const query=input.value.trim().toLowerCase(),saved=getSaved();let total=0;items.forEach(a=>{const category=a.closest('[data-category]').dataset.category;const match=a.dataset.search.includes(query)&&(filter==='all'||filter===category||(filter==='saved'&&saved.includes(a.dataset.slug)));a.hidden=!match;if(match)total++;});groups.forEach(g=>g.hidden=!$$('.tool-link',g).some(a=>!a.hidden));$('#search-count').textContent=`${total} ${total===1?'tool':'tools'}`;$('.no-results',library).hidden=total>0;}
 input.addEventListener('input',update);$$('[data-filter]',library).forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]',library).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));update();}));$('[data-clear-search]',library).addEventListener('click',()=>{input.value='';$('[data-filter="all"]',library).click();input.focus();});window.addEventListener('storage',update);
 const params=new URLSearchParams(location.search);if(params.get('saved')==='1')$('[data-filter="saved"]',library).click();if(params.get('q')){input.value=params.get('q');update();}}
const main=$('[data-calculator]');
if(main){const form=$('#calculator-form'),error=$('#form-error'),output=$('#result-output'),status=$('#result-status');let tool,current,kept,valid=false,timer;const slug=main.dataset.calculator;
 const defaults=()=>Object.fromEntries(tool.fields.map(f=>[f.key,String(f.value??'')]));
 const values=()=>Object.fromEntries(new FormData(form));
 const favourite=$('[data-save]');function paintSaved(){const saved=getSaved().includes(slug);favourite.setAttribute('aria-pressed',String(saved));favourite.textContent=saved?'★':'☆';favourite.setAttribute('aria-label',`${saved?'Unsave':'Save'} ${tool?.title||'calculator'}`);}paintSaved();
 favourite.addEventListener('click',()=>{const saved=getSaved(),isSaved=saved.includes(slug);if(!setSaved(isSaved?saved.filter(x=>x!==slug):[...saved,slug]))status.textContent='Browser storage is unavailable. Favourites could not be saved.';else{paintSaved();status.textContent=isSaved?'Removed from your favourites.':'Saved to this browser’s favourites.';}});
 function compare(){if(!kept||!current)return;$('#scenario').hidden=false;$('#kept-result').textContent=format(kept.value)+(kept.unit?' '+kept.unit:'');$('#current-result').textContent=format(current.value)+(current.unit?' '+current.unit:'');$('#scenario-difference').textContent=typeof current.value==='number'&&typeof kept.value==='number'?`Change: ${current.value-kept.value>0?'+':''}${format(current.value-kept.value)} ${current.unit==='%'?'percentage points':current.unit||''}. Compare the result breakdown for context.`:'Change inputs to compare this result with your kept scenario.';}
 function compute({animate=true,announce=true}={}){if(!tool)return false;try{const presentation=fieldPresentation(tool,values());for(const field of tool.fields){const wrapper=$(`[data-field="${field.key}"]`,form);wrapper.hidden=!presentation[field.key].visible;$('label',wrapper).textContent=presentation[field.key].label;if(wrapper.hidden&&!form.elements.namedItem(field.key).checkValidity())form.elements.namedItem(field.key).value=String(field.value??'');}for(const input of $$('input,select,textarea',form)){input.removeAttribute('aria-invalid');if(!input.checkValidity()){input.setAttribute('aria-invalid','true');throw Error(input.validationMessage||'Check your inputs.');}}
 const v=values();for(const field of tool.fields){if((field.type==='number'||!field.type)&&String(v[field.key]??'').trim()==='')throw Error(`${field.label} is required.`);if(field.type==='select'&&!field.options.some(o=>String(typeof o==='object'?o.value:o)===String(v[field.key])))throw Error(`Choose a supported ${field.label.toLowerCase()}.`);}
 const next=enrichResult(tool,v,tool.calculate(v));const html=resultMarkup(next);current=next;valid=true;output.innerHTML=html;error.textContent='';if(animate){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const number=$('[data-result-value]',output);number.animate(reduced?[{opacity:.55},{opacity:1}]:[{opacity:.3,transform:'translateY(8px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:reduced?120:520,easing:'cubic-bezier(.16,1,.3,1)'});if(!reduced)$('.result-inner',output).classList.add('updated');const indicator=$('[data-calculation-indicator]');indicator.classList.add('visible');indicator.getAnimations().forEach(a=>a.cancel());indicator.animate([{opacity:.2},{opacity:1}],{duration:reduced?120:400});} if(announce)status.textContent='Calculated with your current inputs.';compare();return true;
 }catch(err){valid=false;error.textContent=err.message||'Check your inputs and try again.';status.textContent='The result shown uses the last valid inputs.';return false;}}
 $$('[data-key]').forEach(button=>button.addEventListener('click',()=>{const input=form.elements.namedItem('expression');if(!input)return;const key=button.dataset.key;if(key==='AC')input.value='';else if(key==='⌫')input.value=input.value.slice(0,-1);else input.value+=key;input.dispatchEvent(new Event('input',{bubbles:true}));}));
 form.addEventListener('submit',event=>{event.preventDefault();clearTimeout(timer);if(compute()){if(innerWidth<960)$('.results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}else{$('[aria-invalid=true]',form)?.focus();}});
 form.addEventListener('input',event=>{clearTimeout(timer);if(event.target.type==='number'&&event.target.value==='')return;timer=setTimeout(()=>{if(form.checkValidity())compute({announce:false});},350);});
 form.addEventListener('change',()=>{clearTimeout(timer);compute();});form.addEventListener('reset',()=>{clearTimeout(timer);setTimeout(()=>{compute();status.textContent='Example inputs restored.';},0);});
 $('[data-compare]').addEventListener('click',()=>{if(!compute())return;kept={...current,inputs:values()};compare();status.textContent='Scenario kept. Change an input to compare.';});
 $('[data-clear-scenario]').addEventListener('click',()=>{kept=null;$('#scenario').hidden=true;status.textContent='Comparison cleared.';});
 $('[data-share]').addEventListener('click',async()=>{if(!compute())return;const v=values(),d=defaults();const link=new URL(location.origin+location.pathname);Object.entries(v).forEach(([key,value])=>{if(value!==d[key])link.searchParams.set(key,value);});if(link.href.length>8000){status.textContent='These inputs are too long for a share link. Export the results instead.';return;}const button=$('[data-share]');button.disabled=true;try{await navigator.clipboard.writeText(link.href);status.textContent='Link copied. It contains your inputs; share only what you want others to read.';}catch{status.textContent='Clipboard unavailable. Your share link is shown below.';let fallback=$('#share-link');if(!fallback){fallback=document.createElement('input');fallback.id='share-link';fallback.type='text';fallback.setAttribute('aria-label','Share link containing inputs');fallback.style.width='100%';$('.results').append(fallback);}fallback.value=link.href;fallback.focus();fallback.select();}finally{button.disabled=false;}});
 $('[data-export]').addEventListener('click',()=>{if(!compute())return;const rows=[['Calculator',tool.title],['Result',current.value],['Unit',current.unit||''],['Label',current.label||''],...tool.fields.map(f=>[f.label,values()[f.key]]),...(current.details||[]).map(x=>[x.label,x.value]),['Method',tool.formula],['Notes',current.note||'']];const cell=x=>'"'+(typeof x==='number'?String(x):String(x??'').replace(/^[=+@-]/,"'")).replace(/"/g,'""')+'"';const csv=rows.map(row=>row.map(cell).join(',')).join('\r\n');const link=document.createElement('a'),objectUrl=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));link.href=objectUrl;link.download=slug+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(objectUrl),5000);status.textContent='Results exported as CSV.';});
 try{const module=await import(`/calculators/${main.dataset.module}.mjs`);tool=module.calculators.find(t=>t.slug===slug);if(!tool)throw Error('Calculator definition missing.');const params=new URLSearchParams(location.search);tool.fields.forEach(field=>{if(params.has(field.key)&&params.get(field.key).length<=20000)form.elements.namedItem(field.key).value=params.get(field.key);});paintSaved();compute({animate:false,announce:false});main.dataset.ready='true';if(params.size)status.textContent=valid?'Inputs loaded from your link.':'Some link inputs need correction.';}catch(err){error.textContent='Unable to load the calculator. Reload the page to try again.';console.error(err);}
}
